(async function(){try{const b=atob(window.__MNEMO_V23_GZ||''),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);const ds=new DecompressionStream('gzip'),ab=await new Response(new Blob([u]).stream().pipeThrough(ds)).arrayBuffer(),html=new TextDecoder('utf-8').decode(ab);delete window.__MNEMO_V23_GZ;document.open();document.write(html);document.close()}catch(e){document.body.innerHTML='<pre style="padding:24px;color:#ffb4b4">Falha ao carregar o gerador: '+String(e)+'</pre>';console.error(e)}})();